314:fn wait_for_first_old_completion(completion: &DsaCompletionRecord, t0: u64) -> Option<u64> {
315:    let start = Instant::now();
316:    let mut spins = 0_u64;
317:
318:    loop {
319:        if completion.status() != DSA_COMP_NONE {
320:            return Some(rdtscp().0 - t0);
321:        }
322:
323:        spins = spins.wrapping_add(1);
324:        if spins & (TIMEOUT_CHECK_STRIDE - 1) == 0
325:            && start.elapsed().as_nanos() >= COMPLETION_TIMEOUT_NS
326:        {
327:            return None;
328:        }
329:
330:        core::hint::spin_loop();
331:    }
332:}
