displayContent.text:
// Experiment 1: occupancy-conditioned one-extra-submit latency.
//
// Logical operations are submitted one per MMIO. Prefill K outstanding
// descriptors, then time exactly one additional submit.
//
//   WQ before measured submit:
//   [op 0][op 1] ... [op K-1]  +  [extra op]
//        outstanding K              measured submit
//
// Question: does one more submit stay cheap, or bend as occupancy consumes
// the admission/credit domain?
//
use std::time::Instant;

use hw_eval::dsa::{
    completion_flags_no_cache_control, poll_completion, reset_completion, DsaCompletionRecord,
    DsaHwDesc, DSA_COMP_NONE, DSA_COMP_SUCCESS,
};
use hw_eval::submit::{cycles_to_ns, lfence, rdtscp, WqPortal};

use crate::config::DsaOperationClass;
use crate::report::{
    stats_from_values, SubmitOccupancyExtraTracePoint, SubmitOccupancyResult,
    SubmitOccupancyTraceOutcome,
};

use super::common::{
    count_visible_completions, optional_stats, reset_sample_completions, scan_visible_completions,
    OperationSlots, COMPLETION_TIMEOUT_NS, TIMEOUT_CHECK_STRIDE,
};

const SUBMIT_OCCUPANCY_BENCHMARK: &str = "submit_occupancy_one_extra";

pub(crate) fn bench_submit_occupancy_one_extra(
    wq: &WqPortal,
    occupancies: &[usize],
    operation: DsaOperationClass,
    payload_size: usize,
    trace_until: Option<usize>,
    iterations: usize,
    tsc_freq: u64,
    json: bool,
    results: &mut Vec<SubmitOccupancyResult>,
) {
    let Some(&max_occupancy) = occupancies.iter().max() else {
        return;
    };

    let max_submitted = trace_until
        .unwrap_or(max_occupancy + 1)
        .max(max_occupancy + 1);
    let mut scratch = SubmitOccupancyScratch::new(max_submitted, operation, payload_size);
    scratch.arm_sentinel();
    let operation_class = operation.operation_class_label(payload_size);

    if !json && trace_until.is_none() {
        println!("\n=== {SUBMIT_OCCUPANCY_BENCHMARK} ({operation_class}) ===");
        println!(
            "{:>8} {:>10} {:>10} {:>10} {:>14} {:>14} {:>14}",
            "K", "submitted", "completed", "missing", "extra_tsc", "extra_ns", "first_old_tsc"
        );
    }

    for &k_prefill in occupancies {
        let result = match trace_until {
            Some(trace_until) => collect_trace_result(
                wq,
                &mut scratch,
                k_prefill,
                trace_until,
                operation,
                payload_size,
                iterations,
                tsc_freq,
                &operation_class,
            ),
            None => collect_summary_result(
                wq,
                &mut scratch,
                k_prefill,
                operation,
                payload_size,
                iterations,
                tsc_freq,
                &operation_class,
            ),
        };

        if !json && trace_until.is_none() {
            print_summary_row(&result);
        }
        results.push(result);
    }
}

struct SubmitOccupancyScratch {
    slots: OperationSlots,
    seen: Vec<bool>,
    sentinel_desc: DsaHwDesc,
    sentinel_comp: DsaCompletionRecord,
}

impl SubmitOccupancyScratch {
    fn new(max_slots: usize, operation: DsaOperationClass, payload_size: usize) -> Self {
        let mut scratch = Self {
            slots: OperationSlots::new_with_payload(max_slots, operation, payload_size),
            seen: vec![false; max_slots],
            sentinel_desc: DsaHwDesc::default(),
            sentinel_comp: DsaCompletionRecord::default(),
        };
        scratch
            .sentinel_desc
            .fill_noop(completion_flags_no_cache_control());
        scratch
    }

    fn arm_sentinel(&mut self) {
        self.sentinel_desc.set_completion(&mut self.sentinel_comp);
    }

    fn reset_and_prefill(&mut self, wq: &WqPortal, k_prefill: usize, submitted: usize) {
        reset_sample_completions(&mut self.slots.completions[..submitted]);
        for desc in &self.slots.descriptors[..k_prefill] {
            unsafe { wq.submit(desc) };
        }
    }

    fn count_and_drain(
        &mut self,
        wq: &WqPortal,
        submitted: usize,
        operation: DsaOperationClass,
        payload_size: usize,
        k_prefill: usize,
    ) -> super::common::CompletionOutcome {
        let bounded_outcome = count_visible_completions(
            &self.slots.completions[..submitted],
            &mut self.seen[..submitted],
        );

        reset_completion(&mut self.sentinel_comp);
        drain_with_sentinel(
            wq,
            &self.sentinel_desc,
            &mut self.sentinel_comp,
            operation,
            payload_size,
            k_prefill,
        );

        if bounded_outcome.completed == submitted {
            bounded_outcome
        } else {
            scan_visible_completions(&self.slots.completions[..submitted])
        }
    }
}

fn collect_summary_result(
    wq: &WqPortal,
    scratch: &mut SubmitOccupancyScratch,
    k_prefill: usize,
    operation: DsaOperationClass,
    payload_size: usize,
    iterations: usize,
    tsc_freq: u64,
    operation_class: &str,
) -> SubmitOccupancyResult {
    let submitted = k_prefill + 1;
    let mut completed_counts = Vec::with_capacity(iterations);
    let mut missing_counts = Vec::with_capacity(iterations);
    let mut error_counts = Vec::with_capacity(iterations);
    let mut extra_submit_tsc = Vec::with_capacity(iterations);
    let mut extra_submit_ns = Vec::with_capacity(iterations);
    let mut first_old_tsc = Vec::with_capacity(iterations);
    let mut first_old_ns = Vec::with_capacity(iterations);

    for _ in 0..iterations {
        scratch.reset_and_prefill(wq, k_prefill, submitted);

        lfence();
        let t0 = rdtscp().0;
        unsafe { wq.submit(&scratch.slots.descriptors[k_prefill]) };
        let extra_ticks = rdtscp().0 - t0;

        if k_prefill != 0 {
            if let Some(first_old_ticks) =
                wait_for_first_old_completion(&scratch.slots.completions[0], t0)
            {
                first_old_tsc.push(first_old_ticks);
                first_old_ns.push(cycles_to_ns(first_old_ticks, tsc_freq));
            }
        }

        let outcome = scratch.count_and_drain(wq, submitted, operation, payload_size, k_prefill);
        completed_counts.push(outcome.completed as u64);
        missing_counts.push((submitted - outcome.completed) as u64);
        error_counts.push(outcome.errors as u64);
        extra_submit_tsc.push(extra_ticks);
        extra_submit_ns.push(cycles_to_ns(extra_ticks, tsc_freq));
    }

    SubmitOccupancyResult {
        benchmark: SUBMIT_OCCUPANCY_BENCHMARK.to_string(),
        operation_class: operation_class.to_string(),
        k_prefill,
        submitted,
        trace_until: None,
        completed: Some(stats_from_values(completed_counts)),
        missing: Some(stats_from_values(missing_counts)),
        errors: Some(stats_from_values(error_counts)),
        extra_submit_tsc_ticks: Some(stats_from_values(extra_submit_tsc)),
        extra_submit_ns: Some(stats_from_values(extra_submit_ns)),
        first_old_completion_tsc_ticks: optional_stats(first_old_tsc),
        first_old_completion_ns: optional_stats(first_old_ns),
        extra_submit_trace: Vec::new(),
        trace_outcomes: Vec::new(),
    }
}

fn collect_trace_result(
    wq: &WqPortal,
    scratch: &mut SubmitOccupancyScratch,
    k_prefill: usize,
    trace_until: usize,
    operation: DsaOperationClass,
    payload_size: usize,
    iterations: usize,
    tsc_freq: u64,
    operation_class: &str,
) -> SubmitOccupancyResult {
    let submitted = trace_until.max(k_prefill + 1);
    let mut points = Vec::with_capacity(iterations * (submitted - k_prefill));
    let mut outcomes = Vec::with_capacity(iterations);

    for iteration_index in 0..iterations {
        scratch.reset_and_prefill(wq, k_prefill, submitted);

        for submit_index in k_prefill..submitted {
            lfence();
            let t0 = rdtscp().0;
            unsafe { wq.submit(&scratch.slots.descriptors[submit_index]) };
            let submit_tsc_ticks = rdtscp().0 - t0;
            points.push(SubmitOccupancyExtraTracePoint {
                iteration_index,
                submit_index,
                submit_tsc_ticks,
                submit_ns: cycles_to_ns(submit_tsc_ticks, tsc_freq),
            });
        }

        let outcome = scratch.count_and_drain(wq, submitted, operation, payload_size, k_prefill);
        outcomes.push(SubmitOccupancyTraceOutcome {
            iteration_index,
            completed: outcome.completed,
            missing: submitted - outcome.completed,
            errors: outcome.errors,
        });
    }

    SubmitOccupancyResult {
        benchmark: "submit_occupancy_trace".to_string(),
        operation_class: operation_class.to_string(),
        k_prefill,
        submitted,
        trace_until: Some(trace_until),
        completed: None,
        missing: None,
        errors: None,
        extra_submit_tsc_ticks: None,
        extra_submit_ns: None,
        first_old_completion_tsc_ticks: None,
        first_old_completion_ns: None,
        extra_submit_trace: points,
        trace_outcomes: outcomes,
    }
}

fn print_summary_row(result: &SubmitOccupancyResult) {
    let completed = result
        .completed
        .as_ref()
        .expect("summary row has completed stats");
    let missing = result
        .missing
        .as_ref()
        .expect("summary row has missing stats");
    let extra_submit_tsc = result
        .extra_submit_tsc_ticks
        .as_ref()
        .expect("summary row has submit TSC stats");
    let extra_submit_ns = result
        .extra_submit_ns
        .as_ref()
        .expect("summary row has submit ns stats");
    let first_old = result
        .first_old_completion_tsc_ticks
        .as_ref()
        .map(|stats| stats.median.to_string())
        .unwrap_or_else(|| "-".to_string());

    println!(
        "{:>8} {:>10} {:>10} {:>10} {:>14} {:>14} {:>14}",
        result.k_prefill,
        result.submitted,
        completed.median,
        missing.median,
        extra_submit_tsc.median,
        extra_submit_ns.median,
        first_old
    );
}

fn wait_for_first_old_completion(completion: &DsaCompletionRecord, t0: u64) -> Option<u64> {
    let start = Instant::now();
    let mut spins = 0_u64;

    loop {
        if completion.status() != DSA_COMP_NONE {
            return Some(rdtscp().0 - t0);
        }

        spins = spins.wrapping_add(1);
        if spins & (TIMEOUT_CHECK_STRIDE - 1) == 0
            && start.elapsed().as_nanos() >= COMPLETION_TIMEOUT_NS
        {
            return None;
        }

        core::hint::spin_loop();
    }
}

fn drain_with_sentinel(
    wq: &WqPortal,
    sentinel_desc: &DsaHwDesc,
    sentinel_comp: &mut DsaCompletionRecord,
    operation: DsaOperationClass,
    payload_size: usize,
    k_prefill: usize,
) {
    unsafe { wq.submit(sentinel_desc) };
    let status = poll_completion(sentinel_comp);
    if status != DSA_COMP_SUCCESS {
        panic!(
            "DSA submit-occupancy drain sentinel failed: status {status:#x} \
             (operation={}, k_prefill={k_prefill})",
            operation.operation_class_label(payload_size)
        );
    }
}

