153:impl SubmitOccupancyScratch {
154:    fn new(max_slots: usize, operation: DsaOperationClass, payload_size: usize) -> Self {
155:        Self {
156:            slots: OperationSlots::new_with_payload(max_slots, operation, payload_size),
157:            seen: vec![false; max_slots],
158:            sentinel_comp: DsaCompletionRecord::default(),
159:        }
