162:    fn reset_and_submit_prefill(&mut self, wq: &WqPortal, case: SubmitOccupancyCase) {
163:        reset_sample_completions(&mut self.slots.completions[..case.submitted]);
164:        for desc in &self.slots.descriptors[..case.k_prefill] {
165:            unsafe { wq.submit(desc) };
166:        }
167:    }
