169:    fn time_submit(&self, wq: &WqPortal, submit_index: usize) -> SubmitTiming {
170:        let start_tsc = rdtscp().0;
171:        unsafe { wq.submit(&self.slots.descriptors[submit_index]) };
172:        let elapsed_tsc = rdtscp().0 - start_tsc;
173:        SubmitTiming {
174:            start_tsc,
175:            elapsed_tsc,
176:        }
177:    }
178:
179:    fn first_completion(&self) -> &DsaCompletionRecord {
180:        &self.slots.completions[0]
181:    }
182:
183:    fn finish_iteration(
184:        &mut self,
185:        wq: &WqPortal,
186:        case: SubmitOccupancyCase,
187:        operation: DsaOperationClass,
188:        payload_size: usize,
189:    ) -> CompletionOutcome {
190:        let bounded_outcome = count_visible_completions(
191:            &self.slots.completions[..case.submitted],
192:            &mut self.seen[..case.submitted],
193:        );
194:        self.drain_with_sentinel(wq, operation, payload_size, case.k_prefill);
195:
196:        if bounded_outcome.completed == case.submitted {
197:            bounded_outcome
198:        } else {
199:            scan_visible_completions(&self.slots.completions[..case.submitted])
200:        }
201:    }
202:
203:    fn drain_with_sentinel(
204:        &mut self,
205:        wq: &WqPortal,
206:        operation: DsaOperationClass,
207:        payload_size: usize,
208:        k_prefill: usize,
209:    ) {
210:        let mut sentinel_desc = DsaHwDesc::default();
211:        sentinel_desc.fill_noop(completion_flags_no_cache_control());
212:        reset_completion(&mut self.sentinel_comp);
213:        sentinel_desc.set_completion(&mut self.sentinel_comp);
214:
215:        unsafe { wq.submit(&sentinel_desc) };
216:        let status = poll_completion(&self.sentinel_comp);
217:        if status != DSA_COMP_SUCCESS {
218:            panic!(
219:                "DSA submit-occupancy drain sentinel failed: status {status:#x} \
220:                 (operation={}, k_prefill={k_prefill})",
221:                operation.operation_class_label(payload_size)
222:            );
223:        }
224:    }
225:}
