417:fn wait_for_first_old_completion(completion: &DsaCompletionRecord, t0: u64) -> Option<u64> {
418:    let start = Instant::now();
419:    let mut spins = 0_u64;
420:
421:    loop {
422:        if completion.status() != DSA_COMP_NONE {
423:            return Some(rdtscp().0 - t0);
424:        }
425:
426:        spins = spins.wrapping_add(1);
427:        if spins & (TIMEOUT_CHECK_STRIDE - 1) == 0
428:            && start.elapsed().as_nanos() >= COMPLETION_TIMEOUT_NS
429:        {
430:            return None;
431:        }
432:
433:        core::hint::spin_loop();
434:    }
435:}
