// Experiment 1: occupancy-conditioned one-extra-submit latency.
//
// Logical operations are submitted one per MMIO. Prefill K outstanding
// descriptors, then time exactly one additional submit.
//
//   WQ before measured submit:
//   [op 0][op 1] ... [op K-1]  +  [extra op]
//        outstanding K              measured submit
//
// Question: does one more submit stay cheap, or bend as occupancy consumes
// the admission/credit domain?
//
use std::time::Instant;

use hw_eval::dsa::{
    completion_flags_no_cache_control, poll_completion, reset_completion, DsaCompletionRecord,
    DsaHwDesc, DSA_COMP_NONE, DSA_COMP_SUCCESS,
};
use hw_eval::submit::{cycles_to_ns, lfence, rdtscp, WqPortal};

use crate::config::DsaOperationClass;
use crate::report::{
    stats_from_values, SubmitOccupancyExtraTracePoint, SubmitOccupancyResult,
    SubmitOccupancyTraceOutcome,
};

use super::common::{
    count_visible_completions, optional_stats, reset_sample_completions, scan_visible_completions,
    CompletionOutcome, OperationSlots, COMPLETION_TIMEOUT_NS, TIMEOUT_CHECK_STRIDE,
};

const SUBMIT_OCCUPANCY_BENCHMARK: &str = "submit_occupancy_one_extra";

pub(crate) fn bench_submit_occupancy_one_extra(
    wq: &WqPortal,
    occupancies: &[usize],
    operation: DsaOperationClass,
    payload_size: usize,
    trace_until: Option<usize>,
    iterations: usize,
    tsc_freq: u64,
    json: bool,
    results: &mut Vec<SubmitOccupancyResult>,
) {
    let Some(&max_occupancy) = occupancies.iter().max() else {
        return;
    };

    let max_submitted = trace_until
        .unwrap_or(max_occupancy + 1)
        .max(max_occupancy + 1);
    let mut scratch = SubmitOccupancyScratch::new(max_submitted, operation, payload_size);
    let operation_class = operation.operation_class_label(payload_size);

    if !json && trace_until.is_none() {
        print_summary_header(&operation_class);
    }

    for &k_prefill in occupancies {
        let case = SubmitOccupancyCase::new(k_prefill, trace_until);
        let result = if case.is_trace() {
            run_trace_case(
                wq,
                &mut scratch,
                case,
                operation,
                payload_size,
                iterations,
                tsc_freq,
                &operation_class,
            )
        } else {
            run_summary_case(
                wq,
                &mut scratch,
                case,
                operation,
                payload_size,
                iterations,
                tsc_freq,
                &operation_class,
            )
        };

        if !json && !case.is_trace() {
            print_summary_row(&result);
        }
        results.push(result);
    }
}

#[derive(Clone, Copy)]
struct SubmitOccupancyCase {
    k_prefill: usize,
    submitted: usize,
    trace_until: Option<usize>,
}

impl SubmitOccupancyCase {
    fn new(k_prefill: usize, trace_until: Option<usize>) -> Self {
        let submitted = trace_until.unwrap_or(k_prefill + 1).max(k_prefill + 1);
        Self {
            k_prefill,
            submitted,
            trace_until,
        }
    }

    fn is_trace(self) -> bool {
        self.trace_until.is_some()
    }

    fn measured_submits(self) -> std::ops::Range<usize> {
        self.k_prefill..self.submitted
    }

    fn trace_capacity(self, iterations: usize) -> usize {
        iterations * (self.submitted - self.k_prefill)
    }
}

struct SubmitTiming {
    start_tsc: u64,
    elapsed_tsc: u64,
}

impl SubmitTiming {
    fn ns(&self, tsc_freq: u64) -> u64 {
        cycles_to_ns(self.elapsed_tsc, tsc_freq)
    }

    fn into_trace_point(
        self,
        iteration_index: usize,
        submit_index: usize,
        tsc_freq: u64,
    ) -> SubmitOccupancyExtraTracePoint {
        SubmitOccupancyExtraTracePoint {
            iteration_index,
            submit_index,
            submit_tsc_ticks: self.elapsed_tsc,
            submit_ns: self.ns(tsc_freq),
        }
    }
}

struct SubmitOccupancyScratch {
    slots: OperationSlots,
    seen: Vec<bool>,
    sentinel_comp: DsaCompletionRecord,
}

impl SubmitOccupancyScratch {
    fn new(max_slots: usize, operation: DsaOperationClass, payload_size: usize) -> Self {
        Self {
            slots: OperationSlots::new_with_payload(max_slots, operation, payload_size),
            seen: vec![false; max_slots],
            sentinel_comp: DsaCompletionRecord::default(),
        }
    }

    fn reset_and_submit_prefill(&mut self, wq: &WqPortal, case: SubmitOccupancyCase) {
        reset_sample_completions(&mut self.slots.completions[..case.submitted]);
        for desc in &self.slots.descriptors[..case.k_prefill] {
            unsafe { wq.submit(desc) };
        }
    }

    fn time_submit(&self, wq: &WqPortal, submit_index: usize) -> SubmitTiming {
        let start_tsc = rdtscp().0;
        unsafe { wq.submit(&self.slots.descriptors[submit_index]) };
        let elapsed_tsc = rdtscp().0 - start_tsc;
        SubmitTiming {
            start_tsc,
            elapsed_tsc,
        }
    }

    fn first_completion(&self) -> &DsaCompletionRecord {
        &self.slots.completions[0]
    }

    fn finish_iteration(
        &mut self,
        wq: &WqPortal,
        case: SubmitOccupancyCase,
        operation: DsaOperationClass,
        payload_size: usize,
    ) -> CompletionOutcome {
        let bounded_outcome = count_visible_completions(
            &self.slots.completions[..case.submitted],
            &mut self.seen[..case.submitted],
        );
        self.drain_with_sentinel(wq, operation, payload_size, case.k_prefill);

        if bounded_outcome.completed == case.submitted {
            bounded_outcome
        } else {
            scan_visible_completions(&self.slots.completions[..case.submitted])
        }
    }

    fn drain_with_sentinel(
        &mut self,
        wq: &WqPortal,
        operation: DsaOperationClass,
        payload_size: usize,
        k_prefill: usize,
    ) {
        let mut sentinel_desc = DsaHwDesc::default();
        sentinel_desc.fill_noop(completion_flags_no_cache_control());
        reset_completion(&mut self.sentinel_comp);
        sentinel_desc.set_completion(&mut self.sentinel_comp);

        unsafe { wq.submit(&sentinel_desc) };
        let status = poll_completion(&self.sentinel_comp);
        if status != DSA_COMP_SUCCESS {
            panic!(
                "DSA submit-occupancy drain sentinel failed: status {status:#x} \
                 (operation={}, k_prefill={k_prefill})",
                operation.operation_class_label(payload_size)
            );
        }
    }
}

struct SummarySamples {
    completed_counts: Vec<u64>,
    missing_counts: Vec<u64>,
    error_counts: Vec<u64>,
    extra_submit_tsc: Vec<u64>,
    extra_submit_ns: Vec<u64>,
    first_old_tsc: Vec<u64>,
    first_old_ns: Vec<u64>,
}

impl SummarySamples {
    fn new(iterations: usize) -> Self {
        Self {
            completed_counts: Vec::with_capacity(iterations),
            missing_counts: Vec::with_capacity(iterations),
            error_counts: Vec::with_capacity(iterations),
            extra_submit_tsc: Vec::with_capacity(iterations),
            extra_submit_ns: Vec::with_capacity(iterations),
            first_old_tsc: Vec::with_capacity(iterations),
            first_old_ns: Vec::with_capacity(iterations),
        }
    }

    fn record_first_old(&mut self, ticks: u64, tsc_freq: u64) {
        self.first_old_tsc.push(ticks);
        self.first_old_ns.push(cycles_to_ns(ticks, tsc_freq));
    }

    fn record_submit(
        &mut self,
        case: SubmitOccupancyCase,
        timing: SubmitTiming,
        outcome: CompletionOutcome,
        tsc_freq: u64,
    ) {
        self.completed_counts.push(outcome.completed as u64);
        self.missing_counts
            .push((case.submitted - outcome.completed) as u64);
        self.error_counts.push(outcome.errors as u64);
        self.extra_submit_tsc.push(timing.elapsed_tsc);
        self.extra_submit_ns.push(timing.ns(tsc_freq));
    }

    fn into_result(
        self,
        case: SubmitOccupancyCase,
        operation_class: &str,
    ) -> SubmitOccupancyResult {
        SubmitOccupancyResult {
            benchmark: SUBMIT_OCCUPANCY_BENCHMARK.to_string(),
            operation_class: operation_class.to_string(),
            k_prefill: case.k_prefill,
            submitted: case.submitted,
            trace_until: None,
            completed: Some(stats_from_values(self.completed_counts)),
            missing: Some(stats_from_values(self.missing_counts)),
            errors: Some(stats_from_values(self.error_counts)),
            extra_submit_tsc_ticks: Some(stats_from_values(self.extra_submit_tsc)),
            extra_submit_ns: Some(stats_from_values(self.extra_submit_ns)),
            first_old_completion_tsc_ticks: optional_stats(self.first_old_tsc),
            first_old_completion_ns: optional_stats(self.first_old_ns),
            extra_submit_trace: Vec::new(),
            trace_outcomes: Vec::new(),
        }
    }
}

fn run_summary_case(
    wq: &WqPortal,
    scratch: &mut SubmitOccupancyScratch,
    case: SubmitOccupancyCase,
    operation: DsaOperationClass,
    payload_size: usize,
    iterations: usize,
    tsc_freq: u64,
    operation_class: &str,
) -> SubmitOccupancyResult {
    let mut samples = SummarySamples::new(iterations);

    for _ in 0..iterations {
        scratch.reset_and_submit_prefill(wq, case);

        lfence();
        let timing = scratch.time_submit(wq, case.k_prefill);
        if case.k_prefill != 0 {
            if let Some(first_old_ticks) =
                wait_for_first_old_completion(scratch.first_completion(), timing.start_tsc)
            {
                samples.record_first_old(first_old_ticks, tsc_freq);
            }
        }

        let outcome = scratch.finish_iteration(wq, case, operation, payload_size);
        samples.record_submit(case, timing, outcome, tsc_freq);
    }

    samples.into_result(case, operation_class)
}

fn run_trace_case(
    wq: &WqPortal,
    scratch: &mut SubmitOccupancyScratch,
    case: SubmitOccupancyCase,
    operation: DsaOperationClass,
    payload_size: usize,
    iterations: usize,
    tsc_freq: u64,
    operation_class: &str,
) -> SubmitOccupancyResult {
    let mut points = Vec::with_capacity(case.trace_capacity(iterations));
    let mut outcomes = Vec::with_capacity(iterations);

    for iteration_index in 0..iterations {
        scratch.reset_and_submit_prefill(wq, case);

        for submit_index in case.measured_submits() {
            let timing = scratch.time_submit(wq, submit_index);
            points.push(timing.into_trace_point(iteration_index, submit_index, tsc_freq));
        }

        let outcome = scratch.finish_iteration(wq, case, operation, payload_size);
        outcomes.push(SubmitOccupancyTraceOutcome {
            iteration_index,
            completed: outcome.completed,
            missing: case.submitted - outcome.completed,
            errors: outcome.errors,
        });
    }

    SubmitOccupancyResult {
        benchmark: "submit_occupancy_trace".to_string(),
        operation_class: operation_class.to_string(),
        k_prefill: case.k_prefill,
        submitted: case.submitted,
        trace_until: case.trace_until,
        completed: None,
        missing: None,
        errors: None,
        extra_submit_tsc_ticks: None,
        extra_submit_ns: None,
        first_old_completion_tsc_ticks: None,
        first_old_completion_ns: None,
        extra_submit_trace: points,
        trace_outcomes: outcomes,
    }
}

fn print_summary_header(operation_class: &str) {
    println!("\n=== {SUBMIT_OCCUPANCY_BENCHMARK} ({operation_class}) ===");
    println!(
        "{:>8} {:>10} {:>10} {:>10} {:>14} {:>14} {:>14}",
        "K", "submitted", "completed", "missing", "extra_tsc", "extra_ns", "first_old_tsc"
    );
}

fn print_summary_row(result: &SubmitOccupancyResult) {
    let completed = result
        .completed
        .as_ref()
        .expect("summary row has completed stats");
    let missing = result
        .missing
        .as_ref()
        .expect("summary row has missing stats");
    let extra_submit_tsc = result
        .extra_submit_tsc_ticks
        .as_ref()
        .expect("summary row has submit TSC stats");
    let extra_submit_ns = result
        .extra_submit_ns
        .as_ref()
        .expect("summary row has submit ns stats");
    let first_old = result
        .first_old_completion_tsc_ticks
        .as_ref()
        .map(|stats| stats.median.to_string())
        .unwrap_or_else(|| "-".to_string());

    println!(
        "{:>8} {:>10} {:>10} {:>10} {:>14} {:>14} {:>14}",
        result.k_prefill,
        result.submitted,
        completed.median,
        missing.median,
        extra_submit_tsc.median,
        extra_submit_ns.median,
        first_old
    );
}

fn wait_for_first_old_completion(completion: &DsaCompletionRecord, t0: u64) -> Option<u64> {
    let start = Instant::now();
    let mut spins = 0_u64;

    loop {
        if completion.status() != DSA_COMP_NONE {
            return Some(rdtscp().0 - t0);
        }

        spins = spins.wrapping_add(1);
        if spins & (TIMEOUT_CHECK_STRIDE - 1) == 0
            && start.elapsed().as_nanos() >= COMPLETION_TIMEOUT_NS
        {
            return None;
        }

        core::hint::spin_loop();
    }
}

