from pathlib import Path
base = Path('docs/report/benchmarking/submit_occupancy_huge_memmove_2026-06-01')
keep = {
    'raw_trace_only_k112_iter100_noop.json',
    'raw_trace_only_k112_iter100_memmove_65536.json',
    'raw_trace_only_k112_iter100_memmove_262144.json',
    'raw_trace_only_k112_iter100_memmove_1048576.json',
    'raw_trace_only_k112_iter100_submit_ns_p95.png',
    'raw_trace_only_k112_iter100_submit_ns_p95.pdf',
    'plot_raw_trace_only_iter100_p95.py',
}
removed = []
for path in sorted(base.iterdir()):
    if path.name in keep:
        continue
    if path.is_dir():
        for child in sorted(path.iterdir()):
            child.unlink()
            removed.append(str(child))
        path.rmdir()
        removed.append(str(path) + '/')
    elif path.is_file():
